CREATE COLUMN TABLE "TEST_AP"."OTNN" ("FormCode" INTEGER CS_INT NOT NULL , "Form1099" NVARCHAR(100) NOT NULL , "UserSign" SMALLINT CS_INT, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("FormCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
